head.b:skin:
:root{
  --green:#0b6e3c; --green-2:#0e8a4a; --green-dark:#063f22; --green-deep:#052e18;
  --gold:#d4a017; --gold-light:#f3c94b; --ink:#1b2420; --muted:#5f6f65;
  --bg:#f4f7f4; --card:#ffffff; --line:#e1e9e1; --radius:16px;
  --shadow:0 6px 24px rgba(6,63,34,.10); --shadow-lg:0 16px 40px rgba(6,63,34,.18);
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{font-family:'Hind Siliguri','Noto Sans Bengali',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--ink);font-size:16px;line-height:1.65;-webkit-font-smoothing:antialiased}
a{color:var(--green);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
::selection{background:var(--gold-light)}
/* ============ Header ============ */
.site-header{background:#ffffff;color:var(--ink);position:sticky;top:0;z-index:60;box-shadow:0 2px 14px rgba(6,63,34,.10);border-bottom:1px solid var(--line)}
.header-in{max-width:1200px;margin:0 auto;padding:10px 18px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:13px;color:var(--ink)}
.brand:hover{text-decoration:none}
.brand img{height:50px;width:auto;display:block}
.brand .bname{font-size:27px;font-weight:700;line-height:1.1;letter-spacing:.2px;color:var(--green-dark)}
.brand .btag{font-size:12.5px;color:var(--muted);letter-spacing:.2px}
.header-search{margin-left:auto;display:flex;background:#f2f7f3;border-radius:999px;overflow:hidden;border:2px solid var(--line)}
.header-search:focus-within{border-color:var(--gold)}
.header-search input{border:none;padding:10px 18px;font-size:15px;width:240px;outline:none;font-family:inherit;color:var(--ink)}
.header-search button{background:linear-gradient(180deg,var(--green-2),var(--green));color:#fff;border:none;padding:10px 22px;font-weight:700;cursor:pointer;font-family:inherit;font-size:15px}
.header-search button:hover{filter:brightness(1.06)}
@media(max-width:640px){.header-search{width:100%;margin-left:0}.header-search input{flex:1;width:auto}}
/* ============ Nav ============ */
.main-nav{background:#eef6f0;border-bottom:1px solid var(--line);position:sticky;top:71px;z-index:55}
.nav-in{max-width:1200px;margin:0 auto;padding:0 12px;display:flex;gap:2px;flex-wrap:wrap}
.main-nav a{color:var(--ink);font-weight:600;padding:12px 13px;font-size:15.5px;border-bottom:3px solid transparent;transition:.15s}
.main-nav a:hover{color:var(--green);text-decoration:none;border-bottom-color:var(--gold);background:#f2f8f3}
@media(max-width:640px){.main-nav{top:118px}}
/* ============ Hero ============ */
.hero{background:radial-gradient(900px 340px at 15% -40%,rgba(243,201,75,.30),transparent 60%),linear-gradient(125deg,#fdfbf3,#eef7ee 55%,#e2f2e4);color:var(--ink);border-bottom:1px solid var(--line)}
.hero-in{max-width:1200px;margin:0 auto;padding:44px 18px 40px;text-align:center}
.hero h1{font-size:36px;margin:0 0 8px;font-weight:700;line-height:1.25}
.hero h1 .gold{color:var(--green)}
.hero p{margin:0 auto 20px;max-width:640px;color:#43544a;font-size:17px}
.hero-search{display:flex;max-width:560px;margin:0 auto;background:#fff;border-radius:999px;overflow:hidden;box-shadow:0 10px 30px rgba(6,63,34,.16);border:1px solid var(--line)}
.hero-search input{flex:1;border:none;padding:14px 22px;font-size:16.5px;outline:none;font-family:inherit;color:var(--ink)}
.hero-search button{background:linear-gradient(180deg,var(--green-2),var(--green));color:#fff;border:none;padding:14px 28px;font-weight:700;font-size:16.5px;cursor:pointer;font-family:inherit}
.hero-chips{margin-top:20px;display:flex;gap:9px;justify-content:center;flex-wrap:wrap}
.hero-chips a{background:#ffffff;border:1px solid #cfe0d2;color:var(--green-dark);border-radius:999px;padding:6px 16px;font-size:14.5px;font-weight:600;box-shadow:0 2px 8px rgba(6,63,34,.08)}
.hero-chips a:hover{background:#e8f4ec;text-decoration:none}
.hero-stats{margin-top:22px;display:flex;gap:34px;justify-content:center;flex-wrap:wrap;color:var(--muted);font-size:14.5px}
.hero-stats b{display:block;font-size:21px;color:var(--green-dark)}
/* ============ Layout ============ */
.wrap{max-width:1200px;margin:0 auto;padding:26px 18px 46px}
.layout{display:flex;gap:26px;align-items:flex-start}
.main-col{flex:1 1 auto;min-width:0}
.side-col{flex:0 0 302px;width:302px}
@media(max-width:920px){.layout{flex-direction:column}.side-col{flex:none;width:100%}}
.side-box{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:17px 19px;margin-bottom:20px;box-shadow:var(--shadow)}
.side-box h3{margin:0 0 11px;font-size:17.5px;color:var(--green-dark);border-bottom:2px solid var(--gold);padding-bottom:7px}
.side-box ul{list-style:none;margin:0;padding:0}
.side-box li{padding:6px 0;border-bottom:1px dashed var(--line)}
.side-box li:last-child{border-bottom:none}
.side-box p{margin:0 0 9px;font-size:15px;color:#37463d}
/* ============ Cards ============ */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(248px,1fr));gap:21px}
@media(max-width:520px){.grid{grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:13px}}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;transition:.22s;display:flex;flex-direction:column;box-shadow:0 2px 10px rgba(6,63,34,.05);position:relative}
.card:hover{box-shadow:var(--shadow-lg);transform:translateY(-4px);border-color:#cfe3d2}
.card .thumb{display:block;aspect-ratio:4/3;overflow:hidden;background:#edf3ed;position:relative}
.card .thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .35s}
.card:hover .thumb img{transform:scale(1.06)}
.free-badge{position:absolute;top:10px;left:10px;background:linear-gradient(180deg,var(--gold-light),var(--gold));color:#2a1e00;font-size:12.5px;font-weight:700;border-radius:999px;padding:3px 11px;box-shadow:0 3px 8px rgba(0,0,0,.25);z-index:2}
.card-body{padding:14px 16px 16px;display:flex;flex-direction:column;gap:9px;flex:1}
.card h2{font-size:16.5px;line-height:1.45;margin:0;font-weight:600}
.card h2 a{color:var(--ink)}
.card h2 a:hover{color:var(--green);text-decoration:none}
.card .meta{font-size:13px;color:var(--muted)}
.chips{display:flex;gap:6px;flex-wrap:wrap}
.chip{display:inline-block;background:#e8f4ec;color:var(--green-dark);border:1px solid #c9e5d1;font-size:12.5px;font-weight:600;border-radius:999px;padding:2px 10px}
.chip:hover{background:#d9efe0;text-decoration:none}
.card .go{margin-top:auto}
.btn{display:inline-block;background:linear-gradient(180deg,var(--green-2),var(--green));color:#fff!important;font-weight:700;border-radius:11px;padding:10px 20px;font-size:15px;text-align:center;box-shadow:0 4px 14px rgba(11,110,60,.30);transition:.18s;border:none;cursor:pointer;font-family:inherit}
.btn:hover{filter:brightness(1.08);text-decoration:none;transform:translateY(-1px)}
.btn-block{display:block;width:100%}
.btn-gold{background:linear-gradient(180deg,var(--gold-light),var(--gold));color:#2a1e00!important;box-shadow:0 4px 14px rgba(212,160,23,.35)}
/* ============ Single post ============ */
.post-full{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:28px 30px;box-shadow:var(--shadow)}
@media(max-width:640px){.post-full{padding:20px 17px}}
.post-full h1{font-size:29px;line-height:1.35;margin:0 0 8px;color:var(--green-dark);font-weight:700}
.post-meta{color:var(--muted);font-size:14px;margin-bottom:18px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.post-body{font-size:16.5px;color:#26322b}
.post-body img{border-radius:12px;box-shadow:var(--shadow)}
.dl-box{background:linear-gradient(180deg,#f2f9f3,#e7f3ea);border:1.5px dashed var(--green);border-radius:var(--radius);padding:24px 20px;text-align:center;margin:24px 0}
.dl-box .btn{font-size:18.5px;padding:14px 38px;border-radius:13px}
.dl-box .note{margin-top:11px;font-size:13.5px;color:var(--muted)}
.spec{width:100%;border-collapse:collapse;margin:18px 0;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 10px rgba(6,63,34,.06)}
.spec td{border-bottom:1px solid var(--line);padding:10px 14px;font-size:15px}
.spec tr:last-child td{border-bottom:none}
.spec td:first-child{font-weight:700;background:#f3f8f3;width:175px;color:var(--green-dark)}
.share-row{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0 4px;align-items:center}
.share-row span{font-weight:700;color:var(--green-dark)}
.share-btn{border-radius:999px;padding:7px 17px;font-weight:700;font-size:14.5px;color:#fff!important}
.share-btn:hover{text-decoration:none;filter:brightness(1.1)}
.sh-fb{background:#1877f2}.sh-wa{background:#25d366}.sh-tg{background:#229ed9}
/* ============ Misc ============ */
.pager{display:flex;justify-content:space-between;margin:28px 0 0;gap:10px}
.status-msg{background:#fff7dd;border:1px solid var(--gold);border-radius:12px;padding:14px 18px;margin-bottom:18px}
.ad-slot{margin:18px 0;text-align:center}
.section-title{font-size:22px;color:var(--green-dark);margin:0 0 18px;border-left:5px solid var(--gold);padding-left:12px;font-weight:700}
/* ============ Footer ============ */
.site-footer{background:linear-gradient(180deg,var(--green-dark),var(--green-deep));color:#d8efe0;margin-top:6px}
.footer-in{max-width:1200px;margin:0 auto;padding:38px 18px 0;display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:30px}
@media(max-width:820px){.footer-in{grid-template-columns:1fr}}
.site-footer h4{color:#fff;margin:0 0 12px;font-size:18px;border-bottom:2px solid var(--gold);display:inline-block;padding-bottom:5px}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{padding:4px 0}
.site-footer a{color:#cfe8d6}
.site-footer a:hover{color:var(--gold-light)}
.footer-bottom{border-top:1px solid rgba(255,255,255,.15);margin-top:28px;padding:16px 18px;text-align:center;font-size:14.5px;color:#b9d6c2}
.footer-bottom a{color:var(--gold-light);font-weight:600}
